static int avs_src_create ( struct avs_dev * adev , struct avs_path_module * mod ) { struct avs_tplg_module * t = mod -> template ; struct avs_src_cfg cfg ; cfg . base . cpc = t -> cfg_base -> cpc ; cfg . base . ibs = t -> cfg_base -> ibs ; cfg . base . obs = t -> cfg_base -> obs ; cfg . base . is_pages = t -> cfg_base -> is_pages ; cfg . base . audio_fmt = * t -> in_fmt ; return avs_dsp_init_module ( adev , mod -> module_id , mod -> owner -> instance_id , t -> core_id , t -> domain , & cfg , sizeof ( cfg ) , & mod -> instance_id ) ; } 